RACE_X["race-a17"]=Object.assign(RACE_X["race-a17"]||{},{cs:["using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        for (int i = 1; i < n; i++)\n        {\n            int x = a[i];\n            int j = i - 1;\n            while (j >= 0 && a[j] > x)\n            {\n                a[j + 1] = a[j];\n                j--;\n            }\n            a[j + 1] = x;\n        }\n        Console.WriteLine(a[0]);\n    }\n}", "using System;\n\nclass Program\n{\n    static int[] a, tmp;\n\n    static void SapXep(int l, int r)\n    {\n        if (l >= r) return;\n        int m = (l + r) / 2;\n        SapXep(l, m);\n        SapXep(m + 1, r);\n        int i = l, j = m + 1, k = l;\n        while (i <= m && j <= r)\n        {\n            if (a[i] <= a[j]) tmp[k++] = a[i++];\n            else tmp[k++] = a[j++];\n        }\n        while (i <= m) tmp[k++] = a[i++];\n        while (j <= r) tmp[k++] = a[j++];\n        for (int t = l; t <= r; t++) a[t] = tmp[t];\n    }\n\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        tmp = new int[n];\n        SapXep(0, n - 1);\n        Console.WriteLine(a[0]);\n    }\n}"]});
