const PR17=[{label:"Ví dụ: Sắp xếp trộn",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> a = {38, 27, 43, 3, 9, 82, 10};\nvector<int> tmp(7);\n\nvoid sapXep(int l, int r) {\n    if (l >= r) return;\n    int m = (l + r) / 2;\n    sapXep(l, m);\n    sapXep(m + 1, r);\n    int i = l, j = m + 1, k = l;\n    while (i <= m && j <= r) {\n        if (a[i] <= a[j]) tmp[k++] = a[i++];\n        else tmp[k++] = a[j++];\n    }\n    while (i <= m) tmp[k++] = a[i++];\n    while (j <= r) tmp[k++] = a[j++];\n    for (int t = l; t <= r; t++) a[t] = tmp[t];\n}\n\nint main() {\n    sapXep(0, a.size() - 1);\n    for (int x : a) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i","j"],range:["l","r"]},{type:"cells",of:"tmp",ptr:["k"],label:"tmp (mảng phụ)"}],py:{code:"a = [38, 27, 43, 3, 9, 82, 10]\ntmp = [0] * 7\n\ndef sapXep(l, r):\n    if l >= r:\n        return\n    m = (l + r) // 2\n    sapXep(l, m)\n    sapXep(m + 1, r)\n    i, j, k = l, m + 1, l\n    while i <= m and j <= r:\n        if a[i] <= a[j]:\n            tmp[k] = a[i]\n            i += 1\n        else:\n            tmp[k] = a[j]\n            j += 1\n        k += 1\n    while i <= m:\n        tmp[k] = a[i]\n        i += 1\n        k += 1\n    while j <= r:\n        tmp[k] = a[j]\n        j += 1\n        k += 1\n    for t in range(l, r + 1):\n        a[t] = tmp[t]\n\nsapXep(0, len(a) - 1)\nprint(*a)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a = { 38, 27, 43, 3, 9, 82, 10 };\n    static int[] tmp = new int[7];\n\n    static void SapXep(int l, int r)\n    {\n        if (l >= r) return;\n        int m = (l + r) / 2;\n        SapXep(l, m);\n        SapXep(m + 1, r);\n        int i = l, j = m + 1, k = l;\n        while (i <= m && j <= r)\n        {\n            if (a[i] <= a[j]) tmp[k++] = a[i++];\n            else tmp[k++] = a[j++];\n        }\n        while (i <= m) tmp[k++] = a[i++];\n        while (j <= r) tmp[k++] = a[j++];\n        for (int t = l; t <= r; t++) a[t] = tmp[t];\n    }\n\n    static void Main()\n    {\n        SapXep(0, a.Length - 1);\n        Console.WriteLine(string.Join(\" \", a));\n    }\n}"}},{label:"Ví dụ: Đếm nghịch thế bằng sắp xếp trộn",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> a = {29, 10, 14, 37, 13, 5, 22};\nvector<int> tmp(7);\nlong long dem = 0;\n\nvoid sapXep(int l, int r) {\n    if (l >= r) return;\n    int m = (l + r) / 2;\n    sapXep(l, m);\n    sapXep(m + 1, r);\n    int i = l, j = m + 1, k = l;\n    while (i <= m && j <= r) {\n        if (a[i] <= a[j]) tmp[k++] = a[i++];\n        else {\n            dem += m - i + 1;    // a[j] nhỏ hơn mọi số còn lại ở nửa trái\n            tmp[k++] = a[j++];\n        }\n    }\n    while (i <= m) tmp[k++] = a[i++];\n    while (j <= r) tmp[k++] = a[j++];\n    for (int t = l; t <= r; t++) a[t] = tmp[t];\n}\n\nint main() {\n    sapXep(0, a.size() - 1);\n    cout << dem << \" nghich the\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i","j"],range:["l","r"]},{type:"vars",names:["dem"]}],py:{code:"a = [29, 10, 14, 37, 13, 5, 22]\ntmp = [0] * 7\ndem = 0\n\ndef sapXep(l, r):\n    global dem\n    if l >= r:\n        return\n    m = (l + r) // 2\n    sapXep(l, m)\n    sapXep(m + 1, r)\n    i, j, k = l, m + 1, l\n    while i <= m and j <= r:\n        if a[i] <= a[j]:\n            tmp[k] = a[i]\n            i += 1\n        else:\n            dem += m - i + 1    # a[j] nhỏ hơn mọi số còn lại ở nửa trái\n            tmp[k] = a[j]\n            j += 1\n        k += 1\n    while i <= m:\n        tmp[k] = a[i]\n        i += 1\n        k += 1\n    while j <= r:\n        tmp[k] = a[j]\n        j += 1\n        k += 1\n    for t in range(l, r + 1):\n        a[t] = tmp[t]\n\nsapXep(0, len(a) - 1)\nprint(dem, \"nghich the\")",note:"global dem cho phép hàm sửa biến dem bên ngoài. Kết quả 12, khớp với số lần đổi chỗ của nổi bọt ở Bài 16, nhưng chỉ tốn O(n log n)."},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a = { 29, 10, 14, 37, 13, 5, 22 };\n    static int[] tmp = new int[7];\n    static long dem = 0;\n\n    static void SapXep(int l, int r)\n    {\n        if (l >= r) return;\n        int m = (l + r) / 2;\n        SapXep(l, m);\n        SapXep(m + 1, r);\n        int i = l, j = m + 1, k = l;\n        while (i <= m && j <= r)\n        {\n            if (a[i] <= a[j]) tmp[k++] = a[i++];\n            else\n            {\n                dem += m - i + 1;    // a[j] nhỏ hơn mọi số còn lại ở nửa trái\n                tmp[k++] = a[j++];\n            }\n        }\n        while (i <= m) tmp[k++] = a[i++];\n        while (j <= r) tmp[k++] = a[j++];\n        for (int t = l; t <= r; t++) a[t] = tmp[t];\n    }\n\n    static void Main()\n    {\n        SapXep(0, a.Length - 1);\n        Console.WriteLine(dem + \" nghich the\");\n    }\n}"}},{label:"Ví dụ: Cây lời gọi của sắp xếp trộn",input:"",code:"#include <iostream>\nusing namespace std;\n\nvoid sapXep(int l, int r, int sau) {\n    for (int k = 0; k < sau; k++) cout << \"  \";\n    cout << \"[\" << l << \", \" << r << \"]\\n\";\n    if (l >= r) return;\n    int m = (l + r) / 2;\n    sapXep(l, m, sau + 1);\n    sapXep(m + 1, r, sau + 1);\n}\n\nint main() {\n    sapXep(0, 7, 0);\n    return 0;\n}",py:{code:"def sapXep(l, r, sau):\n    print(\"  \" * sau + f\"[{l}, {r}]\")\n    if l >= r:\n        return\n    m = (l + r) // 2\n    sapXep(l, m, sau + 1)\n    sapXep(m + 1, r, sau + 1)\n\nsapXep(0, 7, 0)",viz:[{type:"calls"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void SapXep(int l, int r, int sau)\n    {\n        for (int k = 0; k < sau; k++) Console.Write(\"  \");\n        Console.WriteLine(\"[\" + l + \", \" + r + \"]\");\n        if (l >= r) return;\n        int m = (l + r) / 2;\n        SapXep(l, m, sau + 1);\n        SapXep(m + 1, r, sau + 1);\n    }\n\n    static void Main()\n    {\n        SapXep(0, 7, 0);\n    }\n}"}}];
